from pathlib import Path
import base64
import hashlib
import sys

root = Path(sys.argv[1]).resolve()
assets = root / "src/main/resources/assets/veilbound/textures/block"

STONE_SHA256 = "1ae0b7b21a97840184eff902f9f02b0cfb78131e1621801f77bd652a545c3ea3"
DEEPSLATE_SHA256 = "158d8abf695f7dad1550a598c1605e3a406d15d4b57feb339198466894adb68d"
STONE_B64 = ""
DEEPSLATE_B64 = ""

def write_exact(name: str, payload_b64: str, expected_sha: str) -> None:
    data = base64.b64decode(payload_b64)
    actual = hashlib.sha256(data).hexdigest()
    if actual != expected_sha:
        raise SystemExit(f"dimensional ore payload hash mismatch for {name}: {actual}")
    path = assets / name
    path.write_bytes(data)
    if hashlib.sha256(path.read_bytes()).hexdigest() != expected_sha:
        raise SystemExit(f"dimensional ore write verification failed for {name}")

write_exact("dimensional_shard_ore.png", STONE_B64, STONE_SHA256)
write_exact("deepslate_dimensional_shard_ore.png", DEEPSLATE_B64, DEEPSLATE_SHA256)
print("VEILBOUND_0167_DIMENSIONAL_ORE_OVERLAY=PASS overlay=shared_prismatic host=vanilla_stone_vanilla_deepslate frames=8")
